record.field:
for record in records:
    if not record.body_plain or not record.channel_id or not record.channel_id.x_account_id:
        continue
    body = record.body_plain
    tweet_ids = []
    for domain in ['twitter.com', 'x.com']:
        if domain in body:
            for part in body.split():
                if domain in part and '/status/' in part:
                    url_parts = part.split('/status/')
                    if len(url_parts) > 1:
                        tweet_id = url_parts[1].split('?')[0].split('/')[0]
                        if tweet_id.isdigit() and tweet_id not in tweet_ids:
                            tweet_ids.append(tweet_id)
    if not tweet_ids:
        continue
    account = record.channel_id.x_account_id
    if not account.active or account.x_connection_status == 'disabled':
        continue
    for tweet_id in tweet_ids:
        env['x.account.task'].sudo().create({
            'account_id': account.id,
            'operation': 'repost',
            'priority': 1,
            'task_context': json.dumps({
                'post': {'post_id': tweet_id},
                'channel_id': record.channel_id.id,
                'source': 'channel_automation',
            }),
        })
